async function apiRequest(endpoint, method, body, targetOrg) {
  return new Promise((resolve) => {
    const args = ["api", "request", "rest", endpoint, "--method", method];
    if (body) {
      args.push("--body", JSON.stringify(body));
    } else if (method === "DELETE") {
      args.push("--body", JSON.stringify({ mode: "raw" }));
    }
    args.push("--target-org", targetOrg);
    const child = spawn("sf", args, {
      stdio: "pipe",
      timeout: 12e4
    });
    let stdout = "";
    let stderr = "";
    child.stdout?.on("data", (data) => {
      stdout += data.toString();
    });
    child.stderr?.on("data", (data) => {
      stderr += data.toString();
    });
    child.on("close", (code) => {
      if (code === 0) {
        try {
          const result = JSON.parse(stdout);
          resolve({ success: true, data: result, rawOutput: stdout });
        } catch {
          resolve({ success: true, data: stdout, rawOutput: stdout });
        }
      } else {
        let errorMessage = "Unknown error";
        if (stdout.trim()) {
          try {
            const errorResult = JSON.parse(stdout);
            if (Array.isArray(errorResult) && errorResult.length > 0) {
              errorMessage = errorResult.map(
                (e) => `${e.errorCode || "ERROR"}: ${e.message || "Unknown"}`
              ).join("; ");
            } else if (errorResult.message) {
              errorMessage = errorResult.message;
            } else {
              errorMessage = stdout.trim();
            }
          } catch {
            errorMessage = stdout.trim();
          }
        }
        if (errorMessage === "Unknown error") {
          const filteredStderr = stderr.split("\n").filter(
            (line) => !line.includes("beta") && !line.includes("Warning") && line.trim()
          ).join("\n").trim();
          errorMessage = filteredStderr || "Unknown error";
        }
        resolve({
          success: false,
          error: errorMessage,
          rawOutput: stdout || stderr
        });
      }
    });
    child.on("error", (err) => {
      resolve({
        success: false,
        error: err.message || "Unknown error"
      });
    });
  });
}
