function detectContentType(filePath) {
  const ext = path.extname(filePath).toLowerCase();
  switch (ext) {
    case ".zip":
      return "application/zip";
    case ".pdf":
      return "application/pdf";
    case ".png":
      return "image/png";
    case ".jpg":
    case ".jpeg":
      return "image/jpeg";
    default:
      return "application/octet-stream";
  }
}
async function uploadContentVersion(filePath, title, targetOrg, contentType) {
  const credsResult = await getOrgCredentials(targetOrg);
  if (!credsResult.success || !credsResult.data) {
    return { success: false, error: credsResult.error || "Failed to get org credentials" };
  }
  const { accessToken, instanceUrl } = credsResult.data;
  const fileName = path.basename(filePath);
  const fileBuffer = fs.readFileSync(filePath);
  const boundary = `----FormBoundary${crypto.randomBytes(16).toString("hex")}`;
  const entityJson = JSON.stringify({
    Title: title,
    PathOnClient: fileName,
    Origin: "H"
  });
  const parts = [];
  parts.push(
    Buffer.from(
      `--${boundary}\r
Content-Disposition: form-data; name="entity_content"\r
Content-Type: application/json\r
\r
` + entityJson + `\r
`
    )
  );
  parts.push(
    Buffer.from(
      `--${boundary}\r
Content-Disposition: form-data; name="VersionData"; filename="${fileName}"\r
Content-Type: ${contentType || detectContentType(filePath)}\r
\r
`
    )
  );
  parts.push(fileBuffer);
  parts.push(Buffer.from(`\r
`));
  parts.push(Buffer.from(`--${boundary}--\r
`));
  const body = Buffer.concat(parts);
  const url = `${instanceUrl}/services/data/v62.0/sobjects/ContentVersion`;
  try {
    const response = await fetch(url, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${accessToken}`,
        "Content-Type": `multipart/form-data; boundary=${boundary}`
      },
      body
    });
    if (!response.ok) {
      const errorText = await response.text();
      return { success: false, error: `Upload failed (${response.status}): ${errorText}` };
    }
    const result = await response.json();
    const contentVersionId = result.id;
    if (!contentVersionId) {
      return { success: false, error: "Upload succeeded but no ContentVersion ID returned" };
    }
    const queryResult = await runSoqlQuery(
      `SELECT ContentDocumentId FROM ContentVersion WHERE Id = '${contentVersionId}' LIMIT 1`,
      targetOrg
    );
    let contentDocumentId = "";
    if (queryResult.success && queryResult.data?.records?.length) {
      contentDocumentId = queryResult.data.records[0].ContentDocumentId;
    }
    return {
      success: true,
      data: { id: contentVersionId, contentDocumentId }
    };
  } catch (error2) {
    return {
      success: false,
      error: `Upload request failed: ${error2 instanceof Error ? error2.message : String(error2)}`
    };
  }
}
