async function startImportUiServer(opts) {
  if (active) {
    active.close();
    active = null;
  }
  const token = randomBytes2(24).toString("hex");
  let applyStarted = false;
  const server2 = http.createServer();
  const timers = {};
  const close = () => {
    if (timers.idle) clearTimeout(timers.idle);
    if (timers.max) clearTimeout(timers.max);
    server2.close();
    if (active && active.server === server2) active = null;
  };
  const touchIdle = () => {
    if (timers.idle) clearTimeout(timers.idle);
    timers.idle = setTimeout(close, IDLE_MS);
  };
  const originOk = (req, port2) => {
    const origin = req.headers.origin;
    if (!origin) return true;
    return origin === `http://127.0.0.1:${port2}` || origin === `http://localhost:${port2}`;
  };
  const authOk = (req, url) => {
    const t = url.searchParams.get("t") || req.headers["x-lsc-token"] || "";
    return !!t && tokensMatch(t, token);
  };
  server2.on("request", async (req, res) => {
    touchIdle();
    const port2 = server2.address().port;
    const url = new URL(req.url || "/", `http://127.0.0.1:${port2}`);
    if (!originOk(req, port2)) {
      res.writeHead(403).end("Forbidden origin");
      return;
    }
    if (!authOk(req, url)) {
      res.writeHead(401).end("Missing or invalid token");
      return;
    }
    if (req.method === "GET" && url.pathname === "/") {
      res.writeHead(200, { "content-type": "text/html; charset=utf-8" });
      res.end(renderImportSpa(token, opts.targetOrg, opts.source.sourceOrg));
      return;
    }
    if (req.method === "GET" && url.pathname === "/diff") {
      res.writeHead(200, { "content-type": "application/json" });
      res.end(JSON.stringify(opts.diff));
      return;
    }
    if (req.method === "POST" && url.pathname === "/apply") {
      if (applyStarted) {
        res.writeHead(409, { "content-type": "application/json" });
        res.end(
          JSON.stringify({
            error: "Apply already ran for this session. Re-run import_config to start a new one."
          })
        );
        return;
      }
      applyStarted = true;
      const chunks = [];
      req.on("data", (c) => chunks.push(c));
      req.on("end", async () => {
        let selection = [];
        try {
          const body = JSON.parse(Buffer.concat(chunks).toString("utf8") || "{}");
          selection = Array.isArray(body.selection) ? body.selection : [];
        } catch {
          res.writeHead(400, { "content-type": "application/json" });
          res.end(JSON.stringify({ error: "Invalid JSON body" }));
          return;
        }
        res.writeHead(200, { "content-type": "application/x-ndjson", "cache-control": "no-cache" });
        const send = (obj) => res.write(JSON.stringify(obj) + "\n");
        try {
          const backup = await backupTarget(opts.targetOrg, opts.categories);
          send({ type: "backup", path: backup.path });
          const onProgress = (e) => send({ type: "progress", ...e });
          const result = await applyConfig({
            targetOrg: opts.targetOrg,
            source: opts.source,
            diff: opts.diff,
            selection,
            onProgress
          });
          const safeOrg = opts.targetOrg.replace(/[^a-zA-Z0-9._-]/g, "_");
          const resultPath = await writeExport(
            `import-result-${safeOrg}-${fileStamp(result.appliedAt)}.json`,
            result
          );
          send({ type: "done", result, resultPath, backupPath: backup.path });
        } catch (err) {
          send({ type: "error", message: err instanceof Error ? err.message : String(err) });
        } finally {
          res.end();
          touchIdle();
        }
      });
      return;
    }
    res.writeHead(404).end("Not found");
  });
  await new Promise((resolve) => server2.listen(0, "127.0.0.1", resolve));
  const port = server2.address().port;
  timers.idle = setTimeout(close, IDLE_MS);
  timers.max = setTimeout(close, MAX_MS);
  active = { server: server2, close };
  return {
    url: `http://127.0.0.1:${port}/?t=${token}`,
    port,
    token,
    close
  };
}

